class Solution:
    def maxProductOfThree(self, nums):
        best = None
        n = len(nums)
        for i in range(n):
            for j in range(i + 1, n):
                for k in range(j + 1, n):
                    p = nums[i] * nums[j] * nums[k]
                    if best is None or p > best:
                        best = p
        return best
